private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int need = 1; // 3 or 4 bytes
    int data = bb.getByte(i) & 0xFF;
    int value = (data << 8) & 0xFF00;

    need = data >> 3;
    while (need-- > 0) {
        if ((i + 1) < bb.limit()) {
            data = bb.getByte(i + 1) & 0xFF;
            value |= data & 0xFF;
            sb.append((char) value);
            i++;
        } else {
            // Handle the case where little endian decoded to a partial character
            sb.append((char) (value | 0xFF000000));
            i++;
            break;
        }
    }
    return i;
}
