public static void forceDeleteOnExit(File file) throws IOException {
    // Register the file for deletion on JVM shutdown
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            if (file.isDirectory()) {
                deleteDirectory(file.getAbsolutePath());
            } else {
                deleteFiles(file.getAbsolutePath());
            }
        } catch (IOException e) {
            throw new RuntimeException("Error deleting file/directory: " + file.getAbsolutePath(), e);
        }
    }));
}

private static void deleteDirectory(String directoryPath) throws IOException {
    File directory = new File(directoryPath);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IOException("Cannot delete non-directory: " + directoryPath);
    }

    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectory(file.getAbsolutePath());
            } else {
                deleteFile(file.getAbsolutePath());
            }
        }
    }

    directory.delete();
}

private static void deleteFile(String filePath) throws IOException {
    File file = new File(filePath);
    if (!file.exists()) {
        throw new IOException("Cannot delete non-existent file: " + filePath);
    }

    file.delete();
}
