public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Step 1: Calculate the total number of vertices
    int totalVertices = resultMap.size();

    // Step 2: Initialize two sets: one for vertices from the first label
    Set<V> set1 = new HashSet<>();
    // Another set for vertices from the second label
    Set<V> set2 = new HashSet<>();

    // Step 3: Partition the label key sets into the two sets
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String label = entry.getKey();
        V vertex = entry.getValue();
        if (label.startsWith("first")) {
            set1.add(vertex);
        } else if (label.startsWith("second")) {
            set2.add(vertex);
        }
    }

    // Step 4: Generate all possible edges between the two sets
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            // Remove duplicates
            if (!vertex1.equals(vertex2)) {
                target.addEdge(vertex1, vertex2);
            }
        }
    }
}
