public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null; // Return null if genericType is not parameterized.
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    // Get the actual type arguments from the parameterized type.
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    // Convert the actual type arguments to Class<?> for return.
    Class<?>[] result = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        if (actualTypeArguments[i] instanceof Class) {
            result[i] = (Class<?>) actualTypeArguments[i];
        } else if (actualTypeArguments[i] instanceof ParameterizedType) {
            // Handle nested parameters if needed.
            result[i] = resolveArguments(actualTypeArguments[i], targetType).itemType;
        } else {
            // Handle other type information if needed.
            throw new UnsupportedOperationException("Unsupported type: " + actualTypeArguments[i]);
        }
    }
    return result;
}
