import java.util.ArrayList;
import java.util.List;

public class DataSplitter {

    public static List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> result = new ArrayList<>();
        long dataFetchDuration = fetchDataDuration(); // Assuming fetchDataDuration() is a method that returns a long value

        // Ensure start time is smaller than end time
        if (start >= end) {
            return result; // Return empty list if start time is not before or equal to end time
        }

        // Calculate the number of time ranges needed
        long duration = end - start;
        long ranges = (long) Math.ceil(duration / dataFetchDuration);

        // Generate time ranges
        for (int i = 0; i < ranges; i++) {
            long startTime = start + i * dataFetchDuration;
            long endTime = Math.min(start + (i + 1) * dataFetchDuration, end);
            result.add(new TimeRange(startTime, endTime));
        }

        return result;
    }
}
