public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int columnIndex = index;
    while (columnIndex < index + len) {
        char c = str.charAt(columnIndex);
        if (c == 0xef) {
            columnIndex++;
            if (columnIndex < index + len && str.charAt(columnIndex) == 0xbb) {
                columnIndex++;
                if (columnIndex < index + len && str.charAt(columnIndex) == 0xbf) {
                    size += 3; // Special case for surrogate pair
                } else {
                    size += 2; // 2-bytes, no further adjustment needed
                }
            } else {
                size += 2; // 1-byte
            }
        } else if (c >= 0xc0 && c <= 0xdf) {
            size += 2; // 110xxxxx
        } else if (c >= 0xe0 && c <= 0xef) {
            size += 3; // 1110xxxxxx
        } else {
            size += 4; // 11110xxxxxxx
        }
        columnIndex++;
    }
    return size;
}
