import org.javatuples.Pair;

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the middle point of the box along the x-axis
    float middleX = box.getCenter().xaxis();

    // Calculate the half-width of the box
    float width = box.getWidth() / 2;

    // Create the left box
    Box2D leftBox = box.withWidth(width)
                               .withLeft(middleX - width)
                               .withRight(middleX);

    // Create the right box
    Box2D rightBox = box.withWidth(width)
                                .withLeft(middleX)
                                .withRight(middleX + width);

    // Return the pair of boxes
    return Pair.with(leftBox, rightBox);
}
