public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder unescaped = new StringBuilder();
    String escaped = JavaUtil.escapeJava(str);
    int len = escaped.length();

    for (int i = 0; i < len; i++) {
        if (escaped.charAt(i) == '\\') {
            if (i + 1 < len) {
                switch (escaped.charAt(i + 1)) {
                    case 'n':
                        unescaped.append('\n');
                        i++;
                        break;
                    case 't':
                        unescaped.append('\t');
                        i++;
                        break;
                    // Add other escape sequences here
                    default:
                        unescaped.append('\\');
                        unescaped.append(escaped.charAt(i + 1));
                        i++;
                        break;
                }
            } else {
                throw new Exception("Unescaped backslash at the end of a string");
            }
        } else {
            unescaped.append(escaped.charAt(i));
        }
    }

    return unescaped.toString();
}
