import java.util.Arrays;
import java.util.Collection;

public class ArrayUtils {

    /**
     * Converts the given Collection into an array of Strings. The returned array does not contain <code>null</code> entries. Note that  {@link Arrays#sort(Object[])} will throw an {@link NullPointerException} if an array element is <code>null</code>.
     * @param collection The collection to convert
     * @return A new array of Strings.
     */
    public static String[] toNoNullStringArray(Collection<?> collection) {
        if (collection == null) {
            throw new IllegalArgumentException("The collection cannot be null");
        }

        // Convert the Collection to an List
        List<Object> list = collection instanceof List ? (List<Object>) collection : collection.stream().collect(Collectors.toList());

        // Filter out null values
        List<String> filteredList = list.stream().filter(item -> item instanceof String).map(Object::toString).collect(Collectors.toList());

        // Return the array
        return filteredList.toArray(new String[filteredList.size()]);
    }
}
