private static <V,E>boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (vertices.size() < 2) {
        return true; // A subgraph with less than 2 vertices is trivially complete.
    }

    Set<V> remainingVertices = new HashSet<>(graph.vertices());

    for (V u : vertices) {
        remainingVertices.remove(u);
        for (V v : remainingVertices) {
            if (!graph.containsEdge(u, v)) {
                return false; // Found an edge that is not between two vertices in the subgraph.
            }
        }
        remainingVertices.add(u);
    }

    return true; // All vertices in the subgraph are connected in a complete way.
}
