private List<T> computeUpperBounds(List<K> keys) {
    List<T> upperBounds = new ArrayList<>();
    int minKey = Integer.MAX_VALUE; // Assume the first key is the minimum
    for (K key : keys) {
        if (key < minKey) {
            minKey = key;
        }
    }
    for (K key : keys) {
        upperBounds.add((T) minKey);
    }
    return upperBounds;
}
