/**
 * Parses thread snapshots from a file within specified time ranges.
 */
public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        String[] tokens;
        ProfileAnalyzeTimeRange timeRange;

        while ((line = reader.readLine()) != null) {
            tokens = line.split(",");
            String snapshotId = tokens[0];
            long timestamp = Long.parseLong(tokens[1]);
            double cpuUsage = Double.parseDouble(tokens[2]);
            int threadId = Integer.parseInt(tokens[3]);
            String status = tokens[4];
            timeRange = timeRanges.stream()
                                        .filter(tr -> tr.getTimeRange().contains(timestamp))
                                        .findFirst()
                                        .orElse(null);

